{"python":"def pilot_policy(trace):
    if not trace:
        return None
    action, label = trace[-1]
    params = json.loads(action.arguments)
    name = action.name
    sub = label.subset if hasattr(label, 'subset') else set()
    if name == 'intake/register_material':
        return None
    if name == 'clinician/review_referral':
        return None
    if name == 'coordinator/assemble_referral':
        src = params.get('source', '')
        if src not in {'reviewed', 'referral'}:
            raise PolicyViolation('Invalid source for assemble_referral')
        return None
    if name == 'care/route_referral' or name == 'research/route_referral':
        agent = name.split('/')[0]
        src = params.get('source', '')
        dest = params.get('destination', '')
        att = params.get('attachment', '')
        rec = params.get('record', '')
        dest_map = {}
        if agent == 'care':
            dest_map = {'local': 'slot:hospital', 'partner': 'slot:scheduler', 'release': 'slot:public'}
        elif agent == 'research':
            dest_map = {'local': 'slot:hospital', 'partner': 'slot:research', 'release': 'slot:lab'}
        allowed_policy = {
            'slot:audit': {'DIAGNOSIS', 'AUTH'},
            'slot:lab': {'PATIENT', 'AUTH'},
            'slot:public': {'PATIENT', 'DIAGNOSIS', 'AUTH'},
            'slot:research': {'PATIENT', 'UNVERIFIED'},
            'slot:scheduler': {'DIAGNOSIS', 'AUTH'}
        }
        write_slots = []
        if dest in dest_map:
            write_slots.append(dest_map[dest])
        if rec == 'audit':
            write_slots.append('slot:audit')
        elif rec == 'public':
            write_slots.append('slot:public')
        for slot in write_slots:
            if slot in allowed_policy:
                if not sub.issubset(allowed_policy[slot]):
                    raise PolicyViolation(f'Category set {sub} not allowed in {slot}')
        return None
    raise PolicyViolation(f'Unknown tool {name}')}"}
